def _normalize(value: str) -> str:
    return " ".join(value.replace("\u00a0", " ").split()).lower()


def _contains_all(text: str, required: list[str]) -> bool:
    haystack = _normalize(text)
    return all(_normalize(item) in haystack for item in required)


